class CustomShape(CustomBaseModel):
    def __init__(self, shape_type, **kwargs):
        super().__init__()
        self.shape_type = shape_type
        self.shape_attributes = kwargs

    def calculate_area(self):
        if self.shape_type == "circle":
            radius = self.shape_attributes.get("radius")
            if radius is None:
                raise ValueError("Radius is required for a circle")
            return math.pi * radius ** 2
        elif self.shape_type == "rectangle":
            length = self.shape_attributes.get("length")
            width = self.shape_attributes.get("width")
            if length is None or width is None:
                raise ValueError("Length and width are required for a rectangle")
            return length * width
        elif self.shape_type == "triangle":
            base = self.shape_attributes.get("base")
            height = self.shape_attributes.get("height")
            if base is None or height is None:
                raise ValueError("Base and height are required for a triangle")
            return 0.5 * base * height
        else:
            raise ValueError(f"Unsupported shape type: {self.shape_type}")
